function q(
  block: 1 | 2 | 3 | 4 | 5,
  topic: string,
  type: "multiple-choice" | "true-false",
  question: string,
  options: string[],
  correct_index: number,
  explanation: string
): SeedQuestion {
  return { block, topic, type, question, options, correct_index, explanation, topic_summary: SUMMARIES[topic] ?? "", further_reading: REFS[topic] ?? [], source: "hardcoded" }
}

export const SEED_QUESTIONS: SeedQuestion[] = [

  // ─────────────────────────────────────────────
  // BLOCK 1 – General Security Concepts
  // ─────────────────────────────────────────────

  // Fundamentals of Security
  q(1,"Fundamentals of Security","multiple-choice","Which of the following BEST describes the 'Confidentiality' component of the CIA triad?",["Ensuring data is accurate and has not been altered","Ensuring data is accessible to authorised users when needed","Ensuring data is only accessible to those with authorised access","Ensuring actions cannot be denied by the party that performed them"],2,"**Confidentiality** means protecting data from unauthorised disclosure. Encryption, access controls, and need-to-know policies are common confidentiality controls. Do not confuse with **Integrity** (accuracy) or **Availability** (accessibility)."),
  q(1,"Fundamentals of Security","multiple-choice","Which security principle ensures that a sender cannot later deny having sent a message?",["Confidentiality","Integrity","Availability","Non-repudiation"],3,"**Non-repudiation** ensures that a party cannot deny having performed an action. Digital signatures are the primary technical mechanism — they tie an action to a specific key pair that only the signer possesses."),
  q(1,"Fundamentals of Security","multiple-choice","A company policy restricts employees to accessing only the systems and data required for their specific job. Which principle does this BEST represent?",["Separation of duties","Least privilege","Defense in depth","Zero Trust"],1,"**Least privilege** limits each user, process, or system to the minimum access rights needed to perform its function. This reduces the damage an attacker can cause if an account is compromised."),
  q(1,"Fundamentals of Security","multiple-choice","Which category of security control includes organisational policies, procedures, and risk management processes?",["Technical","Physical","Operational","Managerial"],3,"**Managerial** (administrative) controls govern the security programme through policies, standards, risk assessments, and procedures. **Operational** controls cover day-to-day practices such as training and configuration management."),
  q(1,"Fundamentals of Security","multiple-choice","A firewall that blocks unauthorised inbound connections is an example of which control TYPE?",["Detective","Corrective","Preventive","Compensating"],2,"**Preventive** controls stop security incidents from occurring. A firewall blocks unauthorised traffic before it can reach internal systems. A **detective** control (e.g. IDS) identifies incidents after they begin."),
  q(1,"Fundamentals of Security","multiple-choice","An IDS that alerts a security team when suspicious traffic is detected is an example of which control type?",["Preventive","Detective","Corrective","Deterrent"],1,"**Detective** controls identify and record security events. An IDS analyses traffic and generates alerts but does not block traffic (that is the role of an IPS, which is preventive/corrective)."),
  q(1,"Fundamentals of Security","multiple-choice","Zero Trust security is based on which core principle?",["Trust internal networks but verify external connections","Never trust, always verify — regardless of network location","Trust users once authenticated","Verify once, trust for the duration of the session"],1,"**Zero Trust** assumes no user, device, or network segment should be inherently trusted. Every access request must be verified continuously, regardless of whether it originates inside or outside the corporate perimeter."),
  q(1,"Fundamentals of Security","multiple-choice","Which of the following BEST describes a compensating control?",["A control that prevents threats before they occur","An alternative control used when the primary control cannot be implemented","A control that detects threats in real time","A control that restores a system after an incident"],1,"**Compensating controls** are alternative measures used when the primary control is not feasible (e.g. due to cost or technical constraints). They must provide equivalent protection to the original control."),
  q(1,"Fundamentals of Security","true-false","Availability in the CIA triad refers to ensuring that data has not been modified without authorisation.",["True","False"],1,"**False.** Availability means systems and data are accessible to authorised users when needed. **Integrity** is the principle that ensures data has not been altered without authorisation."),
  q(1,"Fundamentals of Security","true-false","The AAA framework stands for Authentication, Authorisation, and Accounting.",["True","False"],0,"**True.** AAA is a foundational security framework. **Authentication** verifies identity; **Authorisation** determines what an authenticated entity can do; **Accounting** records what was done for audit and billing purposes."),
  q(1,"Fundamentals of Security","true-false","A corrective control is designed to prevent a security incident from occurring.",["True","False"],1,"**False.** A **corrective** control restores a system to its normal state after an incident has occurred. **Preventive** controls are designed to stop incidents from happening in the first place."),

  // Cryptographic Solutions
  q(1,"Cryptographic Solutions","multiple-choice","Which encryption algorithm is the current symmetric encryption standard, supporting key sizes of 128, 192, or 256 bits?",["DES","3DES","AES","RSA"],2,"**AES** (Advanced Encryption Standard) replaced DES and 3DES as the US government standard. It is a symmetric block cipher used widely in TLS, disk encryption, and VPNs. RSA is asymmetric, not symmetric."),
  q(1,"Cryptographic Solutions","multiple-choice","Asymmetric encryption uses which combination of keys?",["Two private keys — one for each party","A single shared key for both encryption and decryption","A public key to encrypt and a private key to decrypt","A session key negotiated via a certificate"],2,"**Asymmetric** (public-key) encryption uses a mathematically linked key pair. The **public key** encrypts data (or verifies a signature); the **private key** decrypts it (or creates a signature). The private key must never be shared."),
  q(1,"Cryptographic Solutions","multiple-choice","Which hashing algorithm produces a 256-bit digest and is widely used for file integrity and digital signatures?",["MD5","SHA-1","SHA-256","AES-256"],2,"**SHA-256** (part of the SHA-2 family) produces a 256-bit hash. MD5 (128-bit) and SHA-1 (160-bit) are considered cryptographically weak due to collision vulnerabilities. AES-256 is an encryption algorithm, not a hash."),
  q(1,"Cryptographic Solutions","multiple-choice","What is the purpose of adding a 'salt' to a password before hashing?",["To increase the length of the password","To prevent rainbow table attacks by making each hash unique","To encrypt the password using a symmetric key","To create a digital signature"],1,"A **salt** is a random value appended to the password before hashing. Even if two users have the same password, their salted hashes differ, rendering precomputed rainbow tables useless."),
  q(1,"Cryptographic Solutions","multiple-choice","Which cryptographic component binds a public key to the identity of its owner?",["Private key","Certificate Revocation List (CRL)","Digital certificate","Hash digest"],2,"A **digital certificate** (X.509) is issued by a Certificate Authority (CA) and binds a public key to an entity's identity. It enables others to verify that a public key belongs to who claims to own it."),
  q(1,"Cryptographic Solutions","multiple-choice","Elliptic Curve Cryptography (ECC) is preferred over RSA for mobile and IoT devices primarily because:",["ECC requires longer keys to achieve equivalent security","ECC provides equivalent security with significantly smaller key sizes, requiring less processing power","ECC is a symmetric algorithm and faster by nature","ECC does not require a certificate authority"],1,"**ECC** achieves the same security strength as RSA with much shorter keys (e.g. a 256-bit ECC key is roughly equivalent to a 3072-bit RSA key). This makes ECC ideal for resource-constrained environments."),
  q(1,"Cryptographic Solutions","multiple-choice","A birthday attack is used to compromise which cryptographic mechanism?",["Symmetric encryption keys","Asymmetric key exchange","Hashing algorithms","Digital certificates"],2,"A **birthday attack** exploits the birthday paradox to find two different inputs that produce the same hash output (a collision). It targets the hash function itself, not encryption. This is why MD5 and SHA-1 are deprecated."),
  q(1,"Cryptographic Solutions","multiple-choice","Which technique hides a secret message within an ordinary file such as an image, without visibly altering it?",["Encryption","Steganography","Tokenisation","Hashing"],1,"**Steganography** is a form of obfuscation that conceals the existence of a message by hiding it within another file. Unlike encryption (which scrambles data), steganography makes the hidden data invisible to casual inspection."),
  q(1,"Cryptographic Solutions","true-false","MD5 is considered a strong, collision-resistant hashing algorithm suitable for security-sensitive applications.",["True","False"],1,"**False.** MD5 is considered cryptographically broken. Researchers have demonstrated practical collision attacks against MD5, making it unsuitable for security-critical uses. SHA-256 or SHA-3 should be used instead."),
  q(1,"Cryptographic Solutions","true-false","In asymmetric encryption, the public key can be shared openly without compromising the security of encrypted data.",["True","False"],0,"**True.** The public key is designed to be freely distributed. Only the corresponding private key can decrypt data encrypted with the public key, so sharing the public key presents no risk to confidentiality."),
  q(1,"Cryptographic Solutions","true-false","Both TLS and SSH use asymmetric encryption for key exchange but switch to symmetric encryption for bulk data transfer.",["True","False"],0,"**True.** Asymmetric cryptography is computationally expensive, so it is used only to securely exchange a symmetric session key. The symmetric key then encrypts the actual data stream efficiently."),

  // Change Management
  q(1,"Change Management","multiple-choice","What is the PRIMARY security reason for implementing a formal change management process?",["To ensure changes are deployed as quickly as possible","To prevent unauthorised or untested changes that could introduce vulnerabilities","To give developers direct access to production environments","To automate patch deployment"],1,"Change management reduces security risk by ensuring all changes — even minor configuration edits — are requested, reviewed, tested, approved, and documented before implementation. Uncontrolled changes are a leading cause of outages and vulnerability introduction."),
  q(1,"Change Management","multiple-choice","In a formal change management process, what is a rollback plan?",["A plan to accelerate large-scale deployments","A documented procedure to revert to the previous state if a change fails or causes problems","A plan to upgrade all systems simultaneously","A security checklist for developers"],1,"A **rollback plan** ensures that if a change introduces problems, the team can quickly revert to the known-good prior state. Without a rollback plan, failed changes can result in extended downtime or lingering vulnerabilities."),
  q(1,"Change Management","multiple-choice","What body is typically responsible for reviewing and approving significant changes before implementation?",["Help Desk","Change Advisory Board (CAB)","Security Operations Centre (SOC)","Development team"],1,"A **Change Advisory Board (CAB)** includes representatives from relevant teams (IT, security, business) who review proposed changes, assess risk, and approve or reject them. This provides oversight and accountability."),
  q(1,"Change Management","multiple-choice","Which of the following is a key technical implication that must be assessed before a system change is approved?",["The colour scheme of the user interface","Whether the change could create new attack surfaces or break existing security controls","The marketing value of the new feature","The number of users who will notice the change"],1,"Before approving changes, security teams must assess **technical implications** such as new open ports, altered firewall rules, new dependencies, privilege changes, or impacts on backup and monitoring systems."),
  q(1,"Change Management","true-false","Change management processes apply only to major system overhauls; minor configuration changes can be made without approval.",["True","False"],1,"**False.** Change management applies to all changes, including minor configuration edits. Many significant security incidents have resulted from small, undocumented configuration changes creating unexpected vulnerabilities."),
  q(1,"Change Management","true-false","Documenting changes after implementation is an important part of change management, supporting auditability and forensic investigation.",["True","False"],0,"**True.** Post-implementation documentation creates an audit trail that helps with troubleshooting, compliance audits, and forensic investigation. Knowing exactly what changed and when is critical in a security incident."),

  // ─────────────────────────────────────────────
  // BLOCK 2 – Threats, Vulnerabilities & Mitigations
  // ─────────────────────────────────────────────

  // Threat Actors
  q(2,"Threat Actors","multiple-choice","Which type of threat actor is primarily motivated by political or social ideology rather than financial gain?",["Organised crime","Nation-state","Hacktivist","Unskilled attacker"],2,"**Hacktivists** use hacking to promote a political or social cause — examples include defacing websites or leaking documents to embarrass organisations. Unlike organised crime, financial gain is not their primary motivation."),
  q(2,"Threat Actors","multiple-choice","Which threat actor type typically has the greatest resources, most sophisticated capabilities, and tends to target government or critical infrastructure?",["Hacktivist","Insider threat","Nation-state","Unskilled attacker (script kiddie)"],2,"**Nation-state actors** are sponsored by governments and have access to large budgets, advanced custom malware, and intelligence resources. Their targets often include defence, utilities, finance, and healthcare sectors of rival nations."),
  q(2,"Threat Actors","multiple-choice","An employee accidentally clicks a phishing link, causing a ransomware infection. What type of threat actor does this represent?",["Malicious insider threat","Unintentional insider threat","Nation-state actor","Hacktivist"],1,"An **unintentional insider threat** causes harm without malicious intent — often through negligence, poor security hygiene, or falling victim to social engineering. They are distinct from **malicious insiders** who act deliberately."),
  q(2,"Threat Actors","multiple-choice","'Shadow IT' refers to which of the following?",["Malware that hides itself within system processes","IT systems or software deployed within an organisation without IT department knowledge or approval","Government-sponsored surveillance infrastructure","Anonymous hacktivist collectives"],1,"**Shadow IT** occurs when employees or departments use unauthorised tools, cloud services, or devices to get work done. While often well-intentioned, it creates unmanaged risk — data may reside in uncontrolled environments and the organisation has no visibility or control."),
  q(2,"Threat Actors","multiple-choice","Which characteristic BEST describes an unskilled attacker (script kiddie)?",["Uses sophisticated, custom-developed exploits","Has deep knowledge of zero-day vulnerabilities","Uses pre-made hacking tools with limited technical understanding","Is primarily motivated by espionage"],2,"**Unskilled attackers** (script kiddies) rely on automated tools and publicly available exploits without understanding how they work. They may cause significant damage despite limited skill, simply by running existing tools at scale."),
  q(2,"Threat Actors","multiple-choice","In security, an 'attack surface' refers to:",["The total physical area of a data centre","All the points where an attacker could attempt to enter or extract data from an environment","The number of firewalls protecting a network","The severity of a vulnerability"],1,"The **attack surface** is the sum of all potential entry and exit points for attackers — open ports, web interfaces, APIs, physical access points, and human targets. Reducing the attack surface is a core hardening principle."),
  q(2,"Threat Actors","true-false","Hacktivists are primarily motivated by financial gain from their attacks.",["True","False"],1,"**False.** Hacktivists are motivated by **ideological, political, or social causes**. Financial gain is the primary motivator of organised crime, not hacktivists. Common hacktivist tactics include DDoS attacks and website defacement."),
  q(2,"Threat Actors","true-false","Nation-state actors typically have greater resources and more sophisticated capabilities than organised crime groups.",["True","False"],0,"**True.** Nation-state actors are government-funded and may have intelligence agency support, access to zero-day exploits, and significant human and technical resources. Organised crime groups are also highly capable but generally lack the same state-level resources."),

  // Physical Security
  q(2,"Physical Security","multiple-choice","Which physical control is specifically designed to prevent vehicle-borne attacks on buildings or facilities?",["CCTV cameras","Mantrap (access control vestibule)","Bollards","Proximity card readers"],2,"**Bollards** are short, sturdy posts installed at perimeters to stop vehicles from ramming into buildings. They are a critical physical control for high-security sites and government buildings."),
  q(2,"Physical Security","multiple-choice","A mantrap (access control vestibule) BEST mitigates which physical attack?",["Badge cloning","Tailgating (piggybacking)","Shoulder surfing","Dumpster diving"],1,"A **mantrap** uses two sequential locked doors. A person enters the first door and must be authenticated before the second opens. This prevents **tailgating** — where an unauthorised person follows an authorised one through a secure door."),
  q(2,"Physical Security","multiple-choice","An attacker follows a badged employee through a secured door without presenting their own credentials. This is known as:",["Shoulder surfing","Tailgating","Dumpster diving","Piggy-backing"],1,"**Tailgating** (also called piggybacking) is a physical social engineering technique where an unauthorised individual gains entry by closely following an authorised person. Mantraps and security awareness training are the primary mitigations."),
  q(2,"Physical Security","multiple-choice","CCTV surveillance systems are an example of which type of security control?",["Preventive","Deterrent","Detective","Corrective"],2,"**CCTV** is primarily a **detective** control — it records activity so that incidents can be identified and reviewed after the fact. It can also serve as a **deterrent** (people may avoid bad behaviour when cameras are visible)."),
  q(2,"Physical Security","multiple-choice","Access badge cloning attacks copy RFID credentials from a victim's card. The BEST mitigation is to:",["Replace all badges with basic magnetic stripe cards","Implement stronger authentication such as smartcards with a PIN or multi-factor authentication","Remove badge requirements entirely","Install more CCTV cameras"],1,"Badge cloning defeats simple RFID-only systems. Adding a **PIN** or using **smartcards** with cryptographic authentication (or MFA) ensures that stolen badge data alone is insufficient to gain access."),
  q(2,"Physical Security","true-false","Fencing around a facility is primarily a preventive control that provides an absolute barrier to unauthorised access.",["True","False"],1,"**False.** Fencing is primarily a **deterrent and delay** control — it discourages casual intruders and slows determined attackers, but it does not absolutely prevent entry. It must be combined with other controls (cameras, guards, alarms)."),
  q(2,"Physical Security","true-false","A motion sensor that triggers an alarm when movement is detected is an example of a detective security control.",["True","False"],0,"**True.** A motion sensor **detects** activity and generates an alert, making it a **detective** control. It identifies that something is happening but does not prevent entry. If it triggers a door lock, that element would be preventive."),

  // Social Engineering
  q(2,"Social Engineering","multiple-choice","Which social engineering technique involves creating a fabricated scenario (a 'pretext') to manipulate a target into disclosing information?",["Phishing","Vishing","Pretexting","Watering hole"],2,"**Pretexting** involves fabricating a believable scenario — such as impersonating IT support or a bank employee — to build trust and extract sensitive information. It often precedes other attacks."),
  q(2,"Social Engineering","multiple-choice","A highly targeted phishing attack aimed at the CEO of a company is known as:",["Spear phishing","Whaling","Vishing","Smishing"],1,"**Whaling** is phishing specifically targeting high-profile individuals such as executives. The term reflects the idea of going after 'big fish'. Spear phishing targets specific individuals but at any level; whaling is the executive-specific variant."),
  q(2,"Social Engineering","multiple-choice","Smishing attacks are conducted via which communication channel?",["Email","Voice calls","SMS text messages","Social media direct messages"],2,"**Smishing** (SMS phishing) uses text messages to deliver malicious links or requests for sensitive information. As SMS is often perceived as more trustworthy than email, victims may be more easily deceived."),
  q(2,"Social Engineering","multiple-choice","An attacker compromises a legitimate website frequently visited by employees of a target company, then waits for victims to visit. This is called:",["Spear phishing","Pretexting","Watering hole attack","Vishing"],2,"A **watering hole attack** compromises a site the target group routinely visits, infecting visitors with malware. Named after predators waiting at watering holes for prey, it bypasses perimeter defences by using trusted sites."),
  q(2,"Social Engineering","multiple-choice","A social engineer tells a victim 'This offer expires in one hour — act now!' Which motivational trigger is being exploited?",["Authority","Intimidation","Urgency/Scarcity","Social proof"],2,"**Urgency** and **scarcity** create time pressure that inhibits rational thinking. By telling victims they must act immediately, attackers reduce the likelihood that the target will pause to verify the request."),
  q(2,"Social Engineering","multiple-choice","A coordinated campaign that uses fake social media accounts and disinformation to manipulate public opinion about a company or government is an example of:",["Spear phishing","An influence campaign","Pretexting","Impersonation"],1,"**Influence campaigns** use fabricated content, bots, and amplification tactics to shape public perception at scale. They are often associated with nation-state actors and can cause reputational damage without any technical attack."),
  q(2,"Social Engineering","true-false","Vishing attacks use voice calls to trick victims into revealing sensitive information such as passwords or account numbers.",["True","False"],0,"**True.** **Vishing** (voice phishing) involves phone calls where the attacker impersonates trusted entities — banks, tech support, government agencies — to extract sensitive information or direct victims to malicious sites."),
  q(2,"Social Engineering","true-false","Spear phishing attacks are more targeted and personalised than generic phishing campaigns.",["True","False"],0,"**True.** **Spear phishing** is tailored to a specific individual or organisation using information gathered from social media, LinkedIn, or prior reconnaissance. The personalisation makes it significantly more convincing than bulk phishing."),
  q(2,"Social Engineering","true-false","Conducting simulated phishing campaigns within an organisation is an effective way to measure and improve employee security awareness.",["True","False"],0,"**True.** Simulated phishing campaigns establish a baseline, identify susceptible employees, and allow targeted training. Repeated campaigns track improvement over time and reinforce vigilance without real consequences."),

  // Malware
  q(2,"Malware","multiple-choice","Which type of malware encrypts a victim's files and demands payment — typically in cryptocurrency — for the decryption key?",["Virus","Worm","Ransomware","Rootkit"],2,"**Ransomware** encrypts files or entire disks and extorts victims for the decryption key. Major incidents include WannaCry and NotPetya. Mitigations include offline backups, network segmentation, and patching."),
  q(2,"Malware","multiple-choice","Which malware type can self-replicate and spread across networks without requiring any user interaction?",["Virus","Worm","Trojan","Spyware"],1,"A **worm** spreads autonomously by exploiting network vulnerabilities or services. Unlike a **virus**, which requires a user to execute an infected file, worms propagate without any human action."),
  q(2,"Malware","multiple-choice","A rootkit is BEST described as:",["Malware that replicates by attaching to executable files","Malware that provides an attacker with persistent, hidden administrative access to a compromised system","Software that encrypts victim files for ransom","A self-replicating worm that consumes network bandwidth"],1,"A **rootkit** is designed for **persistence and stealth** — it modifies the OS to hide its presence and maintain privileged access. Rootkits are extremely difficult to detect and remove, often requiring OS reinstallation."),
  q(2,"Malware","multiple-choice","A Trojan horse is BEST described as:",["A self-replicating program that spreads via the network","Malware disguised as legitimate software that secretly performs malicious actions","Software that monitors keystrokes","Malware that encrypts files for ransom"],1,"A **Trojan** appears legitimate (a game, utility, or document) but executes malicious code in the background. Unlike viruses and worms, Trojans do not self-replicate — they rely on users to install them."),
  q(2,"Malware","multiple-choice","Infected computers controlled remotely by an attacker through a command-and-control (C2) server are collectively called:",["A rootkit","Ransomware","A botnet","Adware"],2,"A **botnet** is a network of compromised 'zombie' machines under attacker control. Botnets are used for DDoS attacks, spam campaigns, credential stuffing, and distributing other malware."),
  q(2,"Malware","multiple-choice","Malware that is triggered by a specific event — such as a particular date, time, or condition — is called:",["Ransomware","Worm","Logic bomb","Rootkit"],2,"A **logic bomb** lies dormant until a predetermined condition is met (e.g. an employee termination date). It is often planted by malicious insiders and can delete data, send information, or disrupt systems."),
  q(2,"Malware","multiple-choice","Which type of malware captures keyboard input to steal credentials or other sensitive data?",["Adware","Ransomware","Keylogger","Worm"],2,"A **keylogger** records keystrokes and transmits them to an attacker. It can capture passwords, credit card numbers, and other sensitive input. Keyloggers may be software-based or hardware devices attached between the keyboard and computer."),
  q(2,"Malware","true-false","A backdoor provides attackers with remote access to a compromised system, bypassing normal authentication mechanisms.",["True","False"],0,"**True.** A **backdoor** is a secret access method — either intentionally built in by a developer or installed by malware — that allows attackers to access a system without normal authentication, even after the primary vulnerability is patched."),
  q(2,"Malware","true-false","Polymorphic malware changes its code or signature with each infection to evade signature-based antivirus detection.",["True","False"],0,"**True.** **Polymorphic malware** mutates its code while preserving its functionality. Because the signature changes with each copy, traditional signature-based antivirus cannot reliably detect it. Behaviour-based detection is more effective."),
  q(2,"Malware","true-false","Bloatware is a type of malware specifically designed to cause system damage or data theft.",["True","False"],1,"**False.** **Bloatware** is unwanted pre-installed software that consumes storage and resources but is not typically malicious. It differs from malware in that it is not designed to harm or steal — though it may degrade performance and user experience."),

  // Vulnerabilities and Attacks
  q(2,"Vulnerabilities and Attacks","multiple-choice","An attacker inserts malicious SQL code into a login form field to bypass authentication and access the database. This is called:",["Cross-Site Scripting (XSS)","SQL injection","Buffer overflow","Directory traversal"],1,"**SQL injection** inserts malicious SQL statements into input fields that are passed to a database. A classic example is entering `' OR '1'='1` to bypass authentication. Parameterised queries and input validation prevent this attack."),
  q(2,"Vulnerabilities and Attacks","multiple-choice","An attacker injects a malicious script into a website's comment field. When other users view the page, the script executes in their browsers. This is:",["SQL injection","Cross-Site Scripting (XSS)","Cross-Site Request Forgery (CSRF)","Buffer overflow"],1,"**Cross-Site Scripting (XSS)** injects scripts into web pages viewed by other users. The malicious script runs in the victim's browser context, potentially stealing cookies, session tokens, or credentials. Output encoding prevents XSS."),
  q(2,"Vulnerabilities and Attacks","multiple-choice","A buffer overflow attack exploits which programming flaw?",["Weak password policies","Insufficient bounds checking, allowing data to overflow into adjacent memory regions","Unencrypted network protocols","Misconfigured firewall rules"],1,"A **buffer overflow** occurs when a program writes more data to a buffer than it can hold, overwriting adjacent memory. Attackers can use this to overwrite return addresses and execute arbitrary code. Bounds checking and memory-safe languages prevent this."),
  q(2,"Vulnerabilities and Attacks","multiple-choice","A vulnerability that is unknown to the software vendor and for which no patch exists is called:",["A known vulnerability","A zero-day vulnerability","An end-of-life vulnerability","A legacy vulnerability"],1,"A **zero-day** vulnerability has been discovered (possibly by attackers) but not yet disclosed to or patched by the vendor. The name refers to the fact that defenders have had zero days to address it."),
  q(2,"Vulnerabilities and Attacks","multiple-choice","A Cross-Site Request Forgery (CSRF) attack tricks an authenticated user into:",["Entering credentials on a fake website","Unknowingly submitting a request that performs an unintended action on a site they are logged into","Downloading malware from a compromised website","Revealing their private key"],1,"**CSRF** exploits the trust a website has in the user's browser. If a user is logged into their bank and visits a malicious page, the page can silently make requests to the bank using the victim's session. CSRF tokens mitigate this."),
  q(2,"Vulnerabilities and Attacks","multiple-choice","A race condition vulnerability occurs when:",["A server is overwhelmed with too many simultaneous requests","The correct outcome depends on the precise timing of events, which an attacker can manipulate","A buffer is overfilled with more data than it can hold","An attacker intercepts traffic between two parties"],1,"A **race condition** (TOCTOU — Time-of-Check to Time-of-Use) exists when a program makes security decisions based on a resource state that can change between the check and the use. Attackers manipulate timing to exploit the gap."),
  q(2,"Vulnerabilities and Attacks","true-false","Hardware vulnerabilities, such as weaknesses in firmware, can be exploited to gain persistent access that survives OS reinstallation.",["True","False"],0,"**True.** Firmware-level compromises (e.g. BIOS/UEFI rootkits) persist through OS reinstalls and are extremely difficult to detect or remove. Supply chain attacks that compromise firmware at the manufacturing stage are an increasing concern."),
  q(2,"Vulnerabilities and Attacks","true-false","Bluejacking sends unsolicited messages to Bluetooth devices, while Bluesnarfing steals data from Bluetooth-enabled devices.",["True","False"],0,"**True.** **Bluejacking** is relatively harmless — it exploits Bluetooth discovery to send unsolicited messages. **Bluesnarfing** is serious — it exploits vulnerabilities to gain unauthorised access to contacts, messages, and files on a device."),

  // Malicious Activity
  q(2,"Malicious Activity","multiple-choice","A Distributed Denial of Service (DDoS) attack aims to:",["Steal data from a target server","Overwhelm a target with traffic from multiple sources, making it unavailable to legitimate users","Inject malicious code into a website","Intercept communications between two parties"],1,"**DDoS** attacks flood a target with traffic from many compromised sources (a botnet), exhausting its resources (bandwidth, CPU, connections). Mitigation includes CDN-based scrubbing, rate limiting, and upstream filtering."),
  q(2,"Malicious Activity","multiple-choice","DNS cache poisoning involves:",["Overloading DNS servers with excessive queries","Corrupting DNS cache records to redirect users from legitimate sites to malicious ones","Stealing DNS zone file contents","Encrypting DNS queries to prevent interception"],1,"**DNS poisoning** corrupts a resolver's cache with false records, causing users to be silently redirected to attacker-controlled sites — for example, a fake banking site designed to steal credentials (pharming)."),
  q(2,"Malicious Activity","multiple-choice","An on-path attack (formerly called man-in-the-middle) involves:",["Flooding a server with SYN packets","An attacker secretly intercepting and potentially altering communications between two parties","Exploiting a buffer overflow to execute code","Scanning for open ports on a target"],1,"In an **on-path attack**, the attacker positions themselves between the communicating parties, intercepting and potentially modifying traffic in real time. TLS, certificate pinning, and VPNs help mitigate this attack."),
  q(2,"Malicious Activity","multiple-choice","Session hijacking involves:",["Creating a fake login page to capture credentials","Stealing or forging a valid session token to impersonate an already-authenticated user","Sending many authentication requests to lock out an account","Injecting scripts into a web page"],1,"**Session hijacking** steals a valid session ID (often via XSS or sniffing unencrypted traffic) and uses it to impersonate the authenticated user. HTTPS and HttpOnly cookies reduce the attack surface."),
  q(2,"Malicious Activity","multiple-choice","Which of the following BEST describes an Indicator of Compromise (IoC)?",["A planned security assessment","A firewall access control rule","Evidence suggesting that a system may have been breached, such as unusual outbound traffic or unknown processes","A list of approved software applications"],2,"**IoCs** are forensic artefacts — abnormal log entries, strange network connections, unknown processes, unexpected file changes — that suggest a breach has occurred. SIEM and EDR systems help identify and correlate IoCs."),
  q(2,"Malicious Activity","multiple-choice","A directory traversal attack attempts to:",["Crash a web server with excessive requests","Access files outside the intended web root directory by manipulating path variables using sequences like `../`","Intercept session cookies","Inject malicious SQL into a query"],1,"**Directory traversal** exploits insufficient path validation. By including `../../etc/passwd` in a URL, an attacker may read sensitive files outside the intended directory. Input sanitisation and chroot jails prevent this."),
  q(2,"Malicious Activity","true-false","A replay attack captures a valid authentication credential or token and retransmits it to gain unauthorised access.",["True","False"],0,"**True.** In a **replay attack**, the attacker records a legitimate authentication exchange and replays it. Mitigations include timestamps, nonces (numbers used once), and session tokens that expire quickly."),
  q(2,"Malicious Activity","true-false","A volumetric DDoS attack aims to exhaust the target's available bandwidth by sending massive amounts of traffic.",["True","False"],0,"**True.** Volumetric DDoS floods the target's network link with traffic (e.g. UDP floods, ICMP floods, DNS amplification). This is distinct from protocol attacks (which exhaust stateful device resources) and application-layer attacks."),

  // Hardening
  q(2,"Hardening","multiple-choice","Which hardening technique MOST directly reduces the attack surface of a system?",["Installing the latest version of the operating system","Disabling unnecessary services and removing unneeded software","Implementing a password policy","Enabling full-disk encryption"],1,"Disabling services and software that are not needed eliminates potential entry points. Every unnecessary service is an additional attack vector. This is a core principle of the **principle of least functionality**."),
  q(2,"Hardening","multiple-choice","What is the purpose of applying security patches to systems?",["To add new features and improve performance","To fix known vulnerabilities that attackers could exploit","To increase storage capacity","To reduce power consumption"],1,"**Patches** address known vulnerabilities disclosed by vendors. Applying patches promptly eliminates the window of exposure between disclosure and fix. Failure to patch is one of the most common causes of successful attacks."),
  q(2,"Hardening","multiple-choice","A 'secure baseline' configuration BEST describes:",["The default factory settings for a new device","A documented set of minimum security settings that all systems of a given type must meet","The highest possible security configuration for any system","The original OS installation without any patches"],1,"A **secure baseline** defines the standard configuration that all systems of a particular type must meet. It ensures consistent security across the fleet and provides a reference point for detecting configuration drift."),
  q(2,"Hardening","multiple-choice","In Windows environments, which tool is used to centrally enforce security settings such as password policies and software restrictions across many machines?",["Task Manager","Group Policy","Windows Defender","Active Directory Users and Computers"],1,"**Group Policy** (GPO) allows administrators to define and push security configurations — password complexity, account lockout, software restrictions, screen lock timers — to all machines in the domain from a central point."),
  q(2,"Hardening","multiple-choice","SELinux (Security-Enhanced Linux) implements which type of access control?",["Discretionary Access Control (DAC)","Role-Based Access Control (RBAC)","Mandatory Access Control (MAC)","Attribute-Based Access Control (ABAC)"],2,"**SELinux** enforces **Mandatory Access Control (MAC)** — security labels define what processes and users can access, and these rules cannot be overridden even by root. This limits the damage of compromised processes."),
  q(2,"Hardening","true-false","Changing default usernames and passwords on all network devices immediately after installation is a fundamental hardening step.",["True","False"],0,"**True.** Default credentials are widely known and are among the first things attackers try. Devices still using defaults are trivially compromised. This is one of the simplest and most impactful hardening measures."),
  q(2,"Hardening","true-false","A Trusted Operating System (Trusted OS) relies entirely on user behaviour to enforce security and has no built-in mandatory controls.",["True","False"],1,"**False.** A **Trusted OS** has mandatory security controls built into the kernel — typically MAC — that enforce policy regardless of user or application intent. Examples include SELinux, Trusted Solaris, and security-hardened variants of Windows."),

  // ─────────────────────────────────────────────
  // BLOCK 3 – Security Architecture
  // ─────────────────────────────────────────────

  // Data Protection
  q(3,"Data Protection","multiple-choice","'Data at rest' refers to data that is:",["Actively being transmitted across a network","Stored on a device, database, tape, or other storage medium and not currently in transit","Being actively processed in RAM","Scheduled for deletion"],1,"**Data at rest** is stored data — on hard drives, SSDs, databases, USB drives, or backups. It is protected through encryption (e.g. AES-256), access controls, and physical security of storage media."),
  q(3,"Data Protection","multiple-choice","Which data classification label is typically assigned to the most sensitive government or military information?",["Public","Sensitive","Confidential","Top Secret"],3,"**Top Secret** is the highest government classification. Civilian equivalents include Confidential, Secret, and Top Secret. Commercial frameworks use labels like Public, Internal, Confidential, and Restricted."),
  q(3,"Data Protection","multiple-choice","A DLP (Data Loss Prevention) solution is primarily designed to:",["Recover data lost in a disaster","Detect and prevent unauthorised transfer or exposure of sensitive data","Encrypt all data at rest","Block malware at the network perimeter"],1,"**DLP** tools monitor, detect, and block the movement of sensitive data outside authorised channels — such as emailing classified documents to personal accounts or copying data to USB drives."),
  q(3,"Data Protection","multiple-choice","Data that is actively being processed by a CPU or held in RAM is categorised as:",["Data at rest","Data in transit","Data in use","Archived data"],2,"**Data in use** (or data in processing) is the most vulnerable state — it exists in plaintext in memory while being processed. Hardware-based protection (e.g. Trusted Execution Environments) and memory encryption help protect it."),
  q(3,"Data Protection","multiple-choice","Who is primarily responsible for determining the classification level of data and ensuring it is appropriately protected?",["Data custodian","Data processor","Data owner","Data steward"],2,"The **data owner** (usually a business unit leader) is accountable for classifying data and defining how it should be protected. The **data custodian** (typically IT) implements the technical controls the owner requires."),
  q(3,"Data Protection","multiple-choice","Data sovereignty refers to:",["The right of individuals to access their personal data","The principle that data is subject to the laws and regulations of the country where it is stored or processed","The encryption standard applied to sensitive data","The process of classifying data by its sensitivity level"],1,"**Data sovereignty** is critical for multinational organisations — data stored in another country is subject to that country's laws (e.g. GDPR in the EU, China's data laws). Cloud providers must disclose where data is stored."),
  q(3,"Data Protection","true-false","Tokenisation replaces sensitive data with a non-sensitive placeholder (token), with the mapping stored securely in a separate token vault.",["True","False"],0,"**True.** **Tokenisation** substitutes sensitive values (e.g. credit card numbers) with random tokens. The original data is stored only in the token vault. If the database is breached, attackers obtain only meaningless tokens."),
  q(3,"Data Protection","true-false","Encrypting data in transit also protects data stored on servers from unauthorised access.",["True","False"],1,"**False.** Encryption in transit (e.g. TLS) protects data while it moves between systems but provides no protection for data stored on a server. **Encryption at rest** (e.g. AES on the storage layer) protects stored data."),

  // Cyber Resilience and Redundancy
  q(3,"Cyber Resilience and Redundancy","multiple-choice","RAID 1 provides fault tolerance through which mechanism?",["Striping data across multiple drives for performance","Disk mirroring — writing identical data to two or more drives simultaneously","Parity-based error correction across three or more drives","No redundancy — it is used for performance only"],1,"**RAID 1** mirrors data to two or more disks. If one disk fails, the system continues operating using the mirror. It provides excellent read performance and fault tolerance but doubles storage cost."),
  q(3,"Cyber Resilience and Redundancy","multiple-choice","Which backup type backs up ONLY data that has changed since the LAST BACKUP OF ANY TYPE (full or incremental)?",["Full backup","Differential backup","Incremental backup","Snapshot"],2,"An **incremental** backup only captures changes since the last backup of any type. Restoring requires the last full backup plus every incremental since. **Differential** backups capture changes since the last full backup only."),
  q(3,"Cyber Resilience and Redundancy","multiple-choice","Recovery Time Objective (RTO) is BEST defined as:",["The maximum amount of data loss acceptable, measured in time","The maximum acceptable time to restore a system or service after a failure","The frequency at which backups must be taken","The cost of restoring systems after a disaster"],1,"**RTO** is how long the business can tolerate a system being down. It drives decisions about recovery infrastructure — a 4-hour RTO needs very different solutions from a 4-minute RTO."),
  q(3,"Cyber Resilience and Redundancy","multiple-choice","Recovery Point Objective (RPO) is BEST defined as:",["The time required to fully restore a system","The maximum acceptable amount of data loss, measured in time","The minimum uptime percentage required per month","The priority order for recovering different systems"],1,"**RPO** defines how much data loss is acceptable. An RPO of 1 hour means backups must occur at least every hour. RPO directly determines backup frequency — a shorter RPO requires more frequent (and expensive) backup solutions."),
  q(3,"Cyber Resilience and Redundancy","multiple-choice","Which type of redundant site can take over operations IMMEDIATELY with no data loss and minimal switchover time?",["Cold site","Warm site","Hot site","Mobile site"],2,"A **hot site** is a fully operational duplicate of the primary site — same hardware, current data replication, and active systems. It is the most expensive option but provides near-zero RTO and RPO."),
  q(3,"Cyber Resilience and Redundancy","multiple-choice","A Continuity of Operations Plan (COOP) is designed to:",["Detect and respond to security incidents","Ensure an organisation can continue critical functions during and after a disaster or major disruption","Define network segmentation policies","Train employees in security awareness"],1,"A **COOP** ensures that critical business functions can continue during a disruption. It identifies essential functions, alternate facilities, and procedures to maintain operations when normal facilities or systems are unavailable."),
  q(3,"Cyber Resilience and Redundancy","true-false","An incremental backup requires restoring the last full backup plus only the most recent incremental backup.",["True","False"],1,"**False.** Restoring from incrementals requires the last full backup **plus every incremental backup** taken since that full backup, in order. This makes restore more complex and time-consuming than differential backups."),
  q(3,"Cyber Resilience and Redundancy","true-false","A cold site takes longer to become operational than a warm or hot site because it provides only the facility — with no pre-installed equipment or systems.",["True","False"],0,"**True.** A **cold site** is essentially an empty building with power, cooling, and network connectivity. Equipment must be sourced and configured before it is operational, resulting in a high RTO but much lower cost than warm or hot sites."),

  // Security Architecture
  q(3,"Security Architecture","multiple-choice","In the cloud shared responsibility model, which cloud model places the GREATEST security responsibility on the customer?",["Software as a Service (SaaS)","Platform as a Service (PaaS)","Infrastructure as a Service (IaaS)","Function as a Service (FaaS)"],2,"With **IaaS**, the provider manages the physical hardware, hypervisor, and networking, but the customer manages the OS, middleware, runtime, data, and applications. In **SaaS**, the provider manages almost everything; the customer mainly controls user access and data."),
  q(3,"Security Architecture","multiple-choice","Which of the following BEST describes containerisation?",["Physically securing servers in locked racks","Packaging an application with its dependencies into an isolated, portable unit that runs consistently across environments","Virtualising the entire hardware stack, including the OS","Encrypting data in a container file format"],1,"**Containers** (e.g. Docker) bundle an application and its dependencies into an isolated unit. Multiple containers share the host OS kernel, making them lighter than VMs. Security concerns include container escape and insecure images."),
  q(3,"Security Architecture","multiple-choice","Infrastructure as Code (IaC) improves security primarily by:",["Requiring developers to manually configure each server","Enabling infrastructure to be provisioned through version-controlled, auditable configuration files","Eliminating the need for change management","Replacing the need for firewalls"],1,"**IaC** (e.g. Terraform, Ansible) defines infrastructure in code, enabling consistent deployments, peer review of changes, audit trails in version control, and automated compliance checks — all significantly improving security over manual configuration."),
  q(3,"Security Architecture","multiple-choice","Which architecture style isolates application functionality into small, independently deployable services, limiting the blast radius of a compromise?",["Monolithic architecture","Serverless","Microservices","Software-Defined Networking (SDN)"],2,"**Microservices** decompose applications into small, independent services. If one service is compromised, the attacker's access is limited to that service's data and permissions, rather than the entire application."),
  q(3,"Security Architecture","multiple-choice","ICS/SCADA systems present a unique security challenge because they:",["Generate too much log data to monitor effectively","Often run legacy operating systems that cannot be patched without impacting production processes","Are exclusively targeted by nation-state actors","Do not connect to any external networks"],1,"**ICS/SCADA** systems control physical processes (power grids, water treatment, manufacturing). They often run Windows XP or other legacy OS where patching risks disrupting critical operations, creating long-lived, unpatched vulnerabilities."),
  q(3,"Security Architecture","multiple-choice","A Software-Defined Network (SDN) separates which two components?",["Hardware and software","The control plane (routing decisions) and the data plane (packet forwarding)","Internal and external networks","Wired and wireless networks"],1,"**SDN** decouples the **control plane** (which determines routing logic, managed centrally by the SDN controller) from the **data plane** (which forwards packets). This enables programmable, centrally managed network security policies."),
  q(3,"Security Architecture","true-false","In the cloud shared responsibility model, the cloud provider is always responsible for securing the customer's data.",["True","False"],1,"**False.** In all cloud models, **data security is ultimately the customer's responsibility**. The provider secures the infrastructure up to a point defined by the service model, but the customer must classify, encrypt, and control access to their own data."),
  q(3,"Security Architecture","true-false","Serverless computing removes the need for the customer to manage infrastructure, but introduces new attack surfaces such as function event injection.",["True","False"],0,"**True.** In serverless (e.g. AWS Lambda), the provider manages all infrastructure. However, attackers can exploit insecure function triggers, overly permissive IAM roles, or inject malicious event data to manipulate function behaviour."),

  // Security Infrastructure
  q(3,"Security Infrastructure","multiple-choice","A stateful firewall differs from a stateless packet filter because it:",["Only inspects packet headers for IP addresses and ports","Tracks the state of active connections and makes access decisions based on connection context","Operates exclusively at the application layer","Blocks all traffic unless explicitly permitted by application name"],1,"A **stateful firewall** maintains a connection table and allows return traffic for established sessions without explicit rules. A **stateless** filter inspects each packet independently, with no memory of prior packets."),
  q(3,"Security Infrastructure","multiple-choice","The key difference between an IDS and an IPS is that an IPS can:",["Only monitor traffic, not generate alerts","Actively block or drop malicious traffic — not just detect and alert","Only work with encrypted traffic","Only be deployed in-line between the internet and the internal network"],1,"An **IDS** (Intrusion Detection System) monitors and alerts. An **IPS** (Intrusion Prevention System) is deployed in-line and can **block** traffic matching attack signatures. An IPS has higher impact if misconfigured (false positives block legitimate traffic)."),
  q(3,"Security Infrastructure","multiple-choice","A DMZ (demilitarized zone) in network architecture is BEST described as:",["A zone where firewall rules are disabled for testing","A network segment that hosts publicly accessible servers, isolated from the internal trusted network by firewalls","A region where wireless access points are clustered","A backup network used only during failover"],1,"The **DMZ** hosts servers that need to be reachable from the internet (web servers, email servers, DNS) but must not have unrestricted access to the internal network. Two firewalls — one at the perimeter, one between the DMZ and internal network — are typical."),
  q(3,"Security Infrastructure","multiple-choice","Which port does HTTPS use by default?",["80","22","443","3389"],2,"**Port 443** is the default for HTTPS (HTTP over TLS). Port 80 is HTTP (unencrypted), port 22 is SSH, and port 3389 is RDP. Knowing common port numbers is essential for Security+ and for firewall rule analysis."),
  q(3,"Security Infrastructure","multiple-choice","A Web Application Firewall (WAF) is specifically designed to protect against:",["Network-layer volumetric DDoS attacks","Application-layer attacks such as SQL injection and Cross-Site Scripting (XSS)","Wireless protocol vulnerabilities","Physical intrusion into server rooms"],1,"A **WAF** inspects HTTP/HTTPS traffic and applies rules to block known web attack patterns. It operates at Layer 7 and is the primary defence against OWASP Top 10 vulnerabilities in web applications."),
  q(3,"Security Infrastructure","multiple-choice","Network Access Control (NAC) is BEST described as:",["A protocol for routing packets between networks","A system that controls which devices can connect to a network based on their compliance with security policies","A firewall feature for blocking specific ports","A tool for monitoring bandwidth consumption"],1,"**NAC** checks devices before granting network access — verifying that they have up-to-date patches, approved antivirus, and are compliant with security policy. Non-compliant devices may be quarantined or given limited access."),
  q(3,"Security Infrastructure","true-false","A Web Application Firewall (WAF) operates at the application layer and can detect and block SQL injection and XSS attacks.",["True","False"],0,"**True.** WAFs specifically understand HTTP/HTTPS and can inspect request parameters, headers, and body content. They apply signature-based and behavioural rules to block application-layer attacks that network firewalls cannot see."),
  q(3,"Security Infrastructure","true-false","An implicit deny rule at the end of a firewall policy means that any traffic not explicitly permitted by a preceding rule is allowed through.",["True","False"],1,"**False.** An **implicit deny** (or default deny) means all traffic is **blocked** unless explicitly permitted by a rule. This is the correct and secure approach — allow only what is needed, deny everything else."),

  // ─────────────────────────────────────────────
  // BLOCK 4 – Security Operations
  // ─────────────────────────────────────────────

  // Asset and Change Management
  q(4,"Asset and Change Management","multiple-choice","Which mobile deployment model provides the GREATEST organisational control over the device but the LEAST user flexibility?",["BYOD (Bring Your Own Device)","CYOD (Choose Your Own Device)","COPE (Corporate-Owned, Personally Enabled)","COBO (Corporate-Owned, Business Only)"],3,"**COBO** means the organisation owns the device and it is used exclusively for work purposes. No personal use is permitted. This gives the organisation maximum control over security configuration and data but significantly restricts users."),
  q(4,"Asset and Change Management","multiple-choice","Which of the following is the PRIMARY security concern with End-of-Life (EOL) systems?",["They consume excessive network bandwidth","They no longer receive security patches from the vendor, leaving known vulnerabilities permanently unpatched","They are incompatible with modern authentication protocols","They generate too much log data"],1,"**EOL systems** receive no vendor security updates. Known vulnerabilities remain permanently unpatched, making them easy targets. Mitigations include network isolation, compensating controls, and prioritising replacement or upgrade."),
  q(4,"Asset and Change Management","multiple-choice","When disposing of a hard drive that contained sensitive data, which method provides the HIGHEST assurance of data destruction?",["Deleting files and emptying the recycle bin","Reformatting the drive","Degaussing (for magnetic media) or physical destruction (shredding/crushing)","Overwriting once with zeros using a standard tool"],2,"**Degaussing** uses a powerful magnetic field to destroy magnetic media. **Physical destruction** (shredding, disintegrating, melting) ensures data cannot be recovered regardless of drive type. Simple deletion or formatting leaves data recoverable."),
  q(4,"Asset and Change Management","multiple-choice","MDM (Mobile Device Management) enables organisations to:",["Monitor employee internet browsing activity on personal devices","Centrally manage, configure, monitor, and remotely wipe mobile devices","Enforce BYOD policies without any technical controls","Track physical location of all network equipment"],1,"**MDM** platforms push security configurations (encryption, screen lock, approved apps) to enrolled devices, enforce compliance, and provide remote wipe capability if a device is lost or stolen."),
  q(4,"Asset and Change Management","true-false","Asset inventory is a critical security practice because you cannot effectively protect or monitor assets you do not know exist.",["True","False"],0,"**True.** Unmanaged assets — shadow IT, forgotten servers, unpatched IoT devices — are common entry points for attackers. A comprehensive asset inventory is the foundation of every security programme."),
  q(4,"Asset and Change Management","true-false","In a BYOD programme, the organisation is entirely absolved of security responsibility because the device belongs to the employee.",["True","False"],1,"**False.** Even in BYOD, the organisation remains responsible for protecting its **data** on those devices. MDM, containerisation, and acceptable use policies help maintain control over corporate data regardless of device ownership."),

  // Identity and Access Management
  q(4,"Identity and Access Management","multiple-choice","Which authentication factor falls into the 'something you are' category?",["Password","Hardware token","Smart card","Fingerprint scan"],3,"**Something you are** refers to biometric factors — physical or behavioural characteristics such as fingerprints, facial recognition, iris scans, and voice patterns. These cannot be forgotten or easily shared."),
  q(4,"Identity and Access Management","multiple-choice","Multi-factor Authentication (MFA) requires:",["Two or more passwords that must all match","Authentication using at least two factors from DIFFERENT factor categories","A single very long and complex passphrase","Biometric authentication combined with a knowledge-based question"],1,"**MFA** combines factors from at least two different categories (know/have/are). A password plus a fingerprint is MFA. A password plus a security question is NOT MFA — both are 'something you know'."),
  q(4,"Identity and Access Management","multiple-choice","Single Sign-On (SSO) allows users to:",["Use a single identical password across all applications","Authenticate once and gain access to multiple connected systems without re-entering credentials","Share their credentials with other employees safely","Bypass multi-factor authentication requirements"],1,"**SSO** improves user experience and reduces password fatigue. Centralised authentication means users authenticate once (often with strong MFA) and access multiple apps seamlessly. The tradeoff is that a compromised SSO account gives access to all connected systems."),
  q(4,"Identity and Access Management","multiple-choice","Privileged Access Management (PAM) is PRIMARILY designed to:",["Enforce password complexity for all end users","Control, monitor, and audit the use of privileged accounts such as administrator and root accounts","Manage SSO federation across organisations","Issue digital certificates for privileged users"],1,"**PAM** solutions protect the most sensitive accounts — local admin, domain admin, service accounts, root. They enforce just-in-time access, session recording, credential vaulting, and require approval workflows for privileged actions."),
  q(4,"Identity and Access Management","multiple-choice","In Role-Based Access Control (RBAC), access to resources is determined by:",["The security clearance level assigned to the user","The owner of the data deciding who can access it","The role assigned to the user within the organisation","The specific attributes of the user and the resource"],2,"**RBAC** assigns permissions to roles (e.g. 'HR Manager', 'Network Admin'), and users are assigned to roles. This simplifies access management at scale — changing a role's permissions automatically affects all role members."),
  q(4,"Identity and Access Management","multiple-choice","Which access control model is enforced by the operating system or system administrator, with labels attached to data and users that cannot be overridden by data owners?",["DAC (Discretionary Access Control)","RBAC (Role-Based Access Control)","MAC (Mandatory Access Control)","ABAC (Attribute-Based Access Control)"],2,"**MAC** assigns security labels (e.g. Top Secret, Secret) to both data and users. The OS enforces access based on these labels — even the data owner cannot override MAC policy. Used in high-security government systems."),
  q(4,"Identity and Access Management","multiple-choice","Federation in IAM allows:",["All employees to share a single login account","Users from one organisation to use their home credentials to access resources in a partner organisation, via a trust relationship","Biometric authentication across organisational boundaries","Remote desktop access without a VPN"],1,"**Federation** (e.g. using SAML or OIDC) establishes trust between identity providers, enabling users to access partner resources with their own credentials. Examples include logging into a third-party app with your Google account."),
  q(4,"Identity and Access Management","true-false","A Time-based One-Time Password (TOTP) generates a temporary code that is valid only for a short window of time, typically 30 seconds.",["True","False"],0,"**True.** **TOTP** (used by Google Authenticator, Microsoft Authenticator, etc.) generates a code based on the current time and a shared secret. The code changes every 30 seconds, making stolen codes quickly useless."),
  q(4,"Identity and Access Management","true-false","In Mandatory Access Control (MAC), the data owner can grant or revoke access to their files at their own discretion.",["True","False"],1,"**False.** In **MAC**, access is controlled by the **system/OS** based on security labels — the data owner cannot override this. **DAC** (Discretionary Access Control) is the model where the data owner controls access to their own resources."),

  // Security Techniques
  q(4,"Security Techniques","multiple-choice","WPA3 improves upon WPA2 primarily by implementing which authentication protocol that provides stronger protection against offline dictionary attacks?",["EAP-TLS","PEAP","SAE (Simultaneous Authentication of Equals)","RADIUS"],2,"**WPA3** replaces the WPA2 Pre-Shared Key (PSK) handshake with **SAE** (also known as Dragonfly). SAE provides forward secrecy and is resistant to offline dictionary attacks — even if an attacker captures the handshake, they cannot brute-force the password offline."),
  q(4,"Security Techniques","multiple-choice","Which application security testing technique analyses source code without executing it, to find vulnerabilities?",["Dynamic Application Security Testing (DAST)","Penetration testing","Static Application Security Testing (SAST)","Fuzz testing"],2,"**SAST** (Static Analysis) scans source code, bytecode, or binaries for security issues (hard-coded credentials, SQL injection patterns, buffer overflows) without running the program. It integrates into CI/CD pipelines for early detection."),
  q(4,"Security Techniques","multiple-choice","Email security using SPF (Sender Policy Framework) helps prevent:",["Malware in email attachments","Phishing links in email body","Email spoofing by specifying which mail servers are authorised to send email on behalf of a domain","Eavesdropping on email content in transit"],2,"**SPF** is a DNS record that lists authorised mail servers for a domain. When receiving servers check SPF, emails from unauthorised servers fail authentication. SPF alone does not prevent header spoofing — DKIM and DMARC add additional protection."),
  q(4,"Security Techniques","multiple-choice","Endpoint Detection and Response (EDR) solutions are BEST described as:",["Network-perimeter firewalls that inspect incoming traffic","Continuous endpoint monitoring tools that detect threats and provide investigation and response capabilities on the host","Email filtering gateways","Identity management platforms for enforcing MFA"],1,"**EDR** collects detailed endpoint telemetry (process executions, file changes, network connections, registry modifications) and applies analytics to detect threats. It enables security teams to investigate and contain incidents at the endpoint level."),
  q(4,"Security Techniques","multiple-choice","DNS sinkholing is used to:",["Encrypt DNS queries to prevent interception","Redirect queries for known malicious domains to a controlled server, blocking access and identifying infected hosts","Speed up DNS resolution using caching","Monitor DNS zone transfers for unauthorised changes"],1,"**DNS sinkholing** replaces malicious domain records with the address of a sinkhole server. Infected hosts attempting to contact C2 servers are redirected, blocking the communication and identifying compromised machines."),
  q(4,"Security Techniques","true-false","DMARC (Domain-based Message Authentication, Reporting, and Conformance) builds on SPF and DKIM to allow domain owners to specify how receivers should handle emails that fail authentication checks.",["True","False"],0,"**True.** **DMARC** adds a policy layer — domain owners can instruct receivers to quarantine or reject messages failing SPF/DKIM checks, and receive reports on authentication results. Together SPF + DKIM + DMARC dramatically reduce email spoofing."),
  q(4,"Security Techniques","true-false","WPA2-Personal (PSK) uses a RADIUS server for user authentication.",["True","False"],1,"**False.** WPA2-**Personal** uses a **Pre-Shared Key (PSK)** — all users share the same password. WPA2-**Enterprise** uses **802.1X with a RADIUS server**, providing individual user authentication and enabling granular access control."),

  // Vulnerability Management
  q(4,"Vulnerability Management","multiple-choice","A CVSS (Common Vulnerability Scoring System) score provides:",["The estimated cost to remediate a vulnerability","A standardised numerical score (0–10) indicating the severity of a vulnerability","The number of systems worldwide affected by a vulnerability","The time since a vulnerability was first discovered"],1,"**CVSS** scores range from 0 (informational) to 10 (critical). The score considers factors including attack vector, complexity, required privileges, user interaction, and impact on confidentiality, integrity, and availability."),
  q(4,"Vulnerability Management","multiple-choice","Which of the following BEST describes the advantage of a credentialed vulnerability scan over an uncredentialed scan?",["Credentialed scans are performed remotely without network access","Credentialed scans use valid system credentials to perform deeper internal inspection, finding vulnerabilities invisible to external scanning","Uncredentialed scans are always more thorough","Credentialed scans require less time to complete"],1,"**Credentialed scans** log in to the target system and check installed software versions, configuration settings, and patch levels from the inside. This finds far more vulnerabilities than uncredentialed scans, which only see what is externally visible."),
  q(4,"Vulnerability Management","multiple-choice","When a patch for a critical vulnerability is not yet available, the BEST interim action is to:",["Ignore the vulnerability until the vendor releases a patch","Apply a compensating control to reduce the risk, such as blocking the affected port or service","Immediately shut down all affected systems indefinitely","Publicly disclose the vulnerability to pressure the vendor"],1,"When no patch exists, **compensating controls** reduce exposure — disabling the vulnerable feature, blocking access at the firewall, increasing monitoring, or requiring additional authentication. These are documented exceptions, not permanent solutions."),
  q(4,"Vulnerability Management","multiple-choice","Responsible disclosure in vulnerability management means:",["Publishing full exploit code immediately after discovery to maximise public awareness","Privately notifying the affected vendor and allowing a reasonable time to release a patch before public disclosure","Selling vulnerability details to the highest bidder","Reporting only to government agencies, never to the vendor"],1,"**Responsible disclosure** (also called coordinated disclosure) gives vendors time to fix issues before public exposure — typically 90 days. This balances the public interest in knowing about vulnerabilities with the practical need to patch before attackers exploit them."),
  q(4,"Vulnerability Management","true-false","A false positive in vulnerability scanning occurs when the scanner reports a vulnerability that does not actually exist on the target system.",["True","False"],0,"**True.** **False positives** waste remediation resources and reduce trust in scanner results. **False negatives** (missed real vulnerabilities) are more dangerous. Credentialed scans and manual verification reduce both types of errors."),
  q(4,"Vulnerability Management","true-false","Vulnerability scanning and penetration testing are equivalent techniques and can be used interchangeably.",["True","False"],1,"**False.** **Vulnerability scanning** identifies potential weaknesses. **Penetration testing** actively attempts to exploit those weaknesses to confirm impact and demonstrate real-world risk. They complement each other but serve different purposes."),

  // Alerting and Monitoring
  q(4,"Alerting and Monitoring","multiple-choice","A SIEM (Security Information and Event Management) system primarily provides:",["Endpoint antivirus scanning","Real-time blocking of network attacks","Aggregation, correlation, and analysis of log data from multiple sources to identify security events","User identity management and access provisioning"],2,"**SIEM** collects logs from firewalls, servers, endpoints, applications, and cloud services, correlates events against rules, and generates alerts when suspicious patterns emerge. It provides the central visibility needed for incident detection and response."),
  q(4,"Alerting and Monitoring","multiple-choice","SNMP (Simple Network Management Protocol) is used to:",["Authenticate remote users accessing the network","Monitor network device performance metrics and receive trap alerts when thresholds are exceeded","Encrypt management traffic between administrators and devices","Route packets between network segments"],1,"**SNMP** monitors network devices (routers, switches, servers) by polling for metrics (CPU, memory, interface statistics) and receiving trap messages when conditions change. SNMPv3 adds authentication and encryption; earlier versions are considered insecure."),
  q(4,"Alerting and Monitoring","multiple-choice","NetFlow analysis is primarily used to:",["Capture and inspect full packet payloads for malware analysis","Analyse traffic patterns — source/destination IPs, ports, protocols, bytes — without recording packet content","Encrypt traffic between monitoring systems","Configure firewall rules based on observed traffic"],1,"**NetFlow** (and similar protocols like sFlow, IPFIX) exports metadata about network flows. Security teams use it to spot anomalies like large data exfiltration, port scanning, or unusual communication patterns — all without the storage cost of full packet capture."),
  q(4,"Alerting and Monitoring","multiple-choice","SCAP (Security Content Automation Protocol) is used to:",["Automate the correlation of security events in a SIEM","Standardise the way security configurations and vulnerabilities are described, enabling automated compliance checking","Encrypt communications between security tools","Manage user identities across multiple systems"],1,"**SCAP** provides a standard language (including CVE, CVSS, XCCDF, OVAL) for describing security issues and configuration requirements, enabling automated scanning tools to check systems against defined security standards."),
  q(4,"Alerting and Monitoring","multiple-choice","A 'single pane of glass' in a security operations context refers to:",["A transparent physical barrier protecting server room windows","A unified dashboard that consolidates data from multiple security tools, providing a single integrated view","A single firewall that protects the entire enterprise network","A glass-enclosed secure operations centre"],1,"A **single pane of glass** eliminates the need to switch between multiple disparate tools. It reduces alert fatigue, speeds investigation, and gives analysts a holistic view of the security posture from one interface."),
  q(4,"Alerting and Monitoring","true-false","SIEM systems can be configured with correlation rules that generate alerts when sequences of events match patterns associated with known attack techniques.",["True","False"],0,"**True.** SIEM correlation rules detect multi-step attack patterns that individual events would not reveal — for example, multiple failed logins followed by a successful login and then unusual data access, which together suggest credential theft."),
  q(4,"Alerting and Monitoring","true-false","Log aggregation means collecting logs from a single high-value source to keep analysis focused and manageable.",["True","False"],1,"**False.** **Log aggregation** collects logs from ALL relevant sources — firewalls, servers, endpoints, applications, cloud services — into a central repository. Visibility from only one source leaves significant blind spots."),

  // Incident Response
  q(4,"Incident Response","multiple-choice","What is the correct sequence of the incident response process?",["Identification → Preparation → Containment → Eradication → Recovery → Lessons Learned","Preparation → Identification → Containment → Eradication → Recovery → Lessons Learned","Containment → Identification → Preparation → Recovery → Eradication → Lessons Learned","Preparation → Containment → Identification → Eradication → Recovery → Lessons Learned"],1,"The NIST/CompTIA incident response lifecycle is: **Preparation → Identification → Containment → Eradication → Recovery → Lessons Learned**. Preparation happens before an incident; each subsequent phase follows in order."),
  q(4,"Incident Response","multiple-choice","The PRIMARY goal of the containment phase of incident response is to:",["Identify the root cause of the incident","Restore affected systems to normal operation","Prevent the incident from spreading or causing further damage","Document findings for future improvement"],2,"**Containment** stops the spread of an attack — isolating affected systems, blocking C2 channels, resetting compromised credentials. The goal is to limit damage while preserving evidence for forensic analysis."),
  q(4,"Incident Response","multiple-choice","During digital forensics, chain of custody refers to:",["The sequence of steps taken to eradicate malware","The documented record of who collected, handled, transferred, or examined evidence — ensuring its integrity and admissibility","The order in which systems are restored after an incident","The process of notifying affected users"],1,"**Chain of custody** documentation ensures that evidence has not been tampered with between collection and court presentation. Every person who touched the evidence, every transfer, and every action taken must be recorded."),
  q(4,"Incident Response","multiple-choice","Threat hunting differs from traditional reactive security monitoring in that it:",["Responds only to high-severity SIEM alerts","Relies entirely on automated signature-based detection","Proactively searches for threats that may have already evaded existing detection controls","Is performed only during scheduled maintenance windows"],2,"**Threat hunting** assumes adversaries may already be present and uses hypothesis-driven investigation, analytics, and intelligence to find threats that automated tools have missed. It is proactive rather than alert-driven."),
  q(4,"Incident Response","multiple-choice","Root cause analysis (RCA) in incident response is performed to:",["Identify the first responder to the incident","Restore affected systems as quickly as possible","Identify the underlying cause of an incident to prevent it from recurring","Assign legal liability for the breach"],2,"**RCA** digs beneath the immediate cause (a phishing email) to find the underlying issues (lack of MFA, no phishing training, insufficient monitoring) that allowed the attack to succeed. Addressing root causes prevents recurrence."),
  q(4,"Incident Response","true-false","A forensic disk image must be created from the original drive before analysis, in order to preserve the original evidence in its original state.",["True","False"],0,"**True.** Forensic analysis is always performed on a **bitwise copy** (image) of the original, never on the original itself. Working on the original risks altering metadata like access timestamps, potentially corrupting evidence."),
  q(4,"Incident Response","true-false","The lessons learned phase occurs before full system recovery in the incident response process.",["True","False"],1,"**False.** **Lessons learned** is the FINAL phase — it happens after systems have been fully recovered. The team reviews what happened, what worked, what didn't, and what improvements should be made to prevent recurrence."),

  // Investigating an Incident
  q(4,"Investigating an Incident","multiple-choice","Packet capture tools like Wireshark allow forensic investigators to:",["View which users logged into systems and when","Capture and analyse network traffic at the packet level, including payload contents","Monitor CPU and memory utilisation on remote servers","Analyse deleted files recovered from a disk image"],1,"**Packet captures** (pcap files) record all network traffic at the bit level. Analysts can reconstruct sessions, extract transferred files, identify attack tools, and understand exactly what data was sent or received."),
  q(4,"Investigating an Incident","multiple-choice","Which log source is MOST useful for determining whether a specific user account was used to access a system at a particular time?",["Application logs","Network flow data","Authentication and OS security logs","Firewall logs"],2,"**Authentication logs** (Windows Security Event Log, Linux /var/log/auth.log) record login attempts, successes, failures, and privilege use. They are the primary source for establishing who accessed what and when."),
  q(4,"Investigating an Incident","multiple-choice","In digital forensics, metadata refers to:",["The encrypted portions of a document","Data about data — such as file creation timestamp, last modified date, author, GPS coordinates in photos","The actual text content of a file","System performance metrics collected by the OS"],1,"**Metadata** is data that describes other data. In an investigation, metadata can reveal when a file was created, who created it, where a photo was taken, or what application was used — without reading the file's actual content."),
  q(4,"Investigating an Incident","multiple-choice","IPS/IDS logs are particularly valuable in an investigation because they:",["Show file access patterns by users","Record detected attack signatures and policy violations observed in network traffic","Track authentication events across all endpoints","Display bandwidth consumption by application"],1,"**IDS/IPS logs** capture alerts triggered by known attack patterns or anomalous behaviour. They help investigators understand what attacks were attempted, which ones may have succeeded, and the timeline of activity."),
  q(4,"Investigating an Incident","true-false","Firewall logs can help investigators determine which network connections were permitted and which were blocked at the network boundary.",["True","False"],0,"**True.** Firewall logs record each connection attempt, including source IP, destination IP, port, protocol, and the action taken (permit/deny). They are essential for understanding the scope of an attack and external communication patterns."),
  q(4,"Investigating an Incident","true-false","Volatile memory (RAM) analysis tools like Volatility can extract evidence — such as running processes, open network connections, and decrypted data — that would be permanently lost when a system is powered off.",["True","False"],0,"**True.** RAM contains ephemeral artefacts not stored on disk — active processes, network connections, encryption keys, and sometimes plaintext versions of encrypted files. Capturing RAM before powering down a system is a critical forensic step."),

  // Automation and Orchestration
  q(4,"Automation and Orchestration","multiple-choice","SOAR (Security Orchestration, Automation, and Response) platforms are designed to:",["Replace all human security analysts with AI","Automate repetitive security tasks and orchestrate responses across multiple integrated tools","Provide backup and recovery for security tool configurations","Monitor physical security systems"],1,"**SOAR** platforms integrate with existing security tools (SIEM, EDR, ticketing, threat intel) and automate workflows — such as automatically quarantining an endpoint when an EDR alert fires, opening a ticket, and notifying the analyst."),
  q(4,"Automation and Orchestration","multiple-choice","Which of the following is a primary benefit of automating security operations?",["Complete elimination of all security incidents","Guaranteed zero false positives in automated alerts","Faster response times and reduced human error in repetitive tasks","Removal of the need for a security operations team"],1,"Automation reduces the mean time to detect (MTTD) and mean time to respond (MTTR). It ensures consistent execution of repetitive tasks, freeing analysts to focus on complex investigations while routine tasks are handled automatically."),
  q(4,"Automation and Orchestration","multiple-choice","In security automation, APIs (Application Programming Interfaces) are used to:",["Physically connect security appliances in the same rack","Allow different software systems to exchange data and trigger actions programmatically","Encrypt communications between automated systems","Manage user authentication across integrated tools"],1,"**APIs** are the connective tissue of security automation — they allow SOAR platforms, SIEMs, EDR tools, threat intel feeds, and ticketing systems to communicate and trigger actions in each other without manual intervention."),
  q(4,"Automation and Orchestration","multiple-choice","A runbook in security operations is BEST described as:",["An automated penetration testing tool","A documented, step-by-step procedure for responding to a specific type of security event","A firewall rule configuration template","An API for integrating security tools"],1,"**Runbooks** standardise responses to known event types — such as a phishing report, malware alert, or DDoS. They ensure consistent handling, reduce response time, and can be fully or partially automated in SOAR platforms."),
  q(4,"Automation and Orchestration","true-false","Runbooks provide a standardised, documented set of procedures that can be automated in SOAR platforms for consistent incident response.",["True","False"],0,"**True.** Runbooks are the foundation of SOAR automation. When a playbook trigger fires (e.g. a high-severity SIEM alert), the SOAR platform executes the runbook steps — isolating a host, pulling threat intel, creating a ticket — automatically."),
  q(4,"Automation and Orchestration","true-false","Automating all aspects of security operations eliminates all risk of errors in incident response.",["True","False"],1,"**False.** Poorly designed automation can propagate errors at machine speed, create alert storms, or make incorrect response decisions at scale. Human oversight and well-tested playbooks remain essential even in highly automated environments."),

  // ─────────────────────────────────────────────
  // BLOCK 5 – Security Program Management & Oversight
  // ─────────────────────────────────────────────

  // Risk Management
  q(5,"Risk Management","multiple-choice","The formula most commonly used to calculate risk is:",["Threat × Vulnerability","Asset Value × Exposure Factor","Likelihood × Impact","Single Loss Expectancy ÷ Annual Rate of Occurrence"],2,"**Risk = Likelihood × Impact.** Likelihood estimates how probable the threat is to materialise. Impact estimates the consequences if it does. This product determines risk priority and drives investment in controls."),
  q(5,"Risk Management","multiple-choice","Which risk management strategy transfers the financial consequences of risk to a third party?",["Risk avoidance","Risk mitigation","Risk transference","Risk acceptance"],2,"**Risk transference** (e.g. purchasing cyber insurance or outsourcing a function) shifts the financial burden of a risk to another party. The risk itself is not eliminated — only the financial liability is shared."),
  q(5,"Risk Management","multiple-choice","A Risk Register is BEST described as:",["A hardware appliance for detecting threats","A document that records identified risks, their likelihood, impact, assigned owner, and mitigation status","A list of all past security incidents","An inventory of all software licences"],1,"The **risk register** is the central record of the organisation's risk management programme. It tracks each risk through its lifecycle — identification, assessment, treatment, monitoring — and assigns ownership for accountability."),
  q(5,"Risk Management","multiple-choice","Quantitative risk analysis differs from qualitative analysis primarily because it:",["Uses subjective labels such as High, Medium, Low","Relies on expert opinion without numerical data","Produces specific monetary values for potential losses (e.g. Annual Loss Expectancy)","Is always less accurate than qualitative methods"],2,"**Quantitative** analysis uses numbers and formulae (ALE = SLE × ARO). It enables cost-benefit analysis of controls — spending £50k on a control to mitigate a £500k ALE is clearly justified. **Qualitative** uses relative ratings and expert judgement."),
  q(5,"Risk Management","multiple-choice","Annual Loss Expectancy (ALE) is calculated as:",["SLE + ARO","SLE × ARO","Asset Value × Exposure Factor","ARO ÷ SLE"],1,"**ALE = SLE × ARO** (Single Loss Expectancy × Annual Rate of Occurrence). SLE is the monetary loss from a single incident; ARO is the expected frequency per year. ALE is the expected annual loss from a specific risk."),
  q(5,"Risk Management","multiple-choice","Which risk management strategy means discontinuing the activity that creates the risk?",["Risk mitigation","Risk transference","Risk avoidance","Risk acceptance"],2,"**Risk avoidance** eliminates the risk by stopping the risky activity — e.g. deciding not to collect certain personal data at all, rather than trying to secure it. It is appropriate when the risk outweighs the benefit of the activity."),
  q(5,"Risk Management","true-false","Risk acceptance means the organisation has decided to tolerate a risk because the cost of mitigation exceeds the potential loss or the risk is within the organisation's defined risk tolerance.",["True","False"],0,"**True.** **Risk acceptance** is a deliberate, documented decision — not an oversight. It is appropriate for low-impact risks or when controls are too costly. Accepted risks must be monitored and reviewed periodically."),
  q(5,"Risk Management","true-false","Qualitative risk analysis produces precise monetary figures for the expected annual cost of each risk.",["True","False"],1,"**False.** **Qualitative** analysis uses relative ratings (High/Medium/Low) based on expert judgement — it does not produce monetary figures. **Quantitative** analysis uses formulae like ALE = SLE × ARO to produce specific monetary values."),

  // Third-party Vendor Risks
  q(5,"Third-party Vendor Risks","multiple-choice","A supply chain attack targets which aspect of an organisation's security?",["The physical supply chain for hardware delivery","A vendor, supplier, or software provider in order to compromise the end customer through the trusted relationship","The organisation's internal network supply infrastructure","Financial supply chain processes"],1,"**Supply chain attacks** exploit trusted relationships — a less-secure vendor is compromised, and the attack reaches the target organisation through legitimate software updates, services, or hardware. The SolarWinds attack is a prominent example."),
  q(5,"Third-party Vendor Risks","multiple-choice","Before engaging a new vendor with access to sensitive data, a 'vendor assessment' typically includes:",["Only reviewing the vendor's pricing","Evaluating the vendor's security controls, policies, compliance certifications (e.g. SOC 2, ISO 27001), and incident history","Asking the vendor to sign a non-disclosure agreement only","Installing monitoring software on the vendor's systems"],1,"**Vendor assessment** (due diligence) evaluates whether a potential vendor's security posture is adequate before granting access. Common methods include security questionnaires, reviewing certifications, requesting penetration test reports, and auditing controls."),
  q(5,"Third-party Vendor Risks","multiple-choice","A 'right-to-audit' clause in a vendor contract gives the customer:",["The right to terminate the contract immediately for any reason","The contractual right to inspect the vendor's security controls, practices, and compliance","The ability to modify the vendor's software","Access to the vendor's other customers' data for comparison"],1,"A **right-to-audit** clause ensures the customer can verify the vendor's security claims through direct inspection rather than relying solely on self-reported questionnaires or certifications."),
  q(5,"Third-party Vendor Risks","multiple-choice","A Business Associate Agreement (BAA) is required under HIPAA when:",["A company purchases health insurance for its employees","A covered entity shares Protected Health Information (PHI) with a third-party vendor","Any vendor provides IT services to a hospital","A vendor stores financial data on behalf of a healthcare company"],1,"**HIPAA** requires a BAA whenever a **covered entity** (healthcare provider, insurer, etc.) shares PHI with a **business associate** (cloud provider, IT firm, analytics company). The BAA obligates the vendor to protect PHI according to HIPAA requirements."),
  q(5,"Third-party Vendor Risks","true-false","Third-party vendors with access to an organisation's systems or data extend the organisation's attack surface.",["True","False"],0,"**True.** Every connected third party is a potential attack vector. Attackers frequently target suppliers, contractors, and service providers as a path to higher-value targets. Vendor risk management is therefore integral to enterprise security."),
  q(5,"Third-party Vendor Risks","true-false","Once a vendor has been onboarded and contracts signed, ongoing security monitoring of that vendor is no longer necessary.",["True","False"],1,"**False.** Vendors must be monitored continuously — their security posture can change, staff can turn over, breaches can occur. Annual reviews, continuous monitoring feeds, and re-assessments on contract renewal are standard practice."),

  // Governance and Compliance
  q(5,"Governance and Compliance","multiple-choice","Information security governance is BEST described as:",["The day-to-day management of IT infrastructure and operations","The strategic framework of policies, roles, accountabilities, and processes that direct and control the security programme","Firewall rule management and network segmentation","The technical implementation of security controls"],1,"**Security governance** sets direction from the top — defining what must be protected, who is responsible, what the risk appetite is, and how compliance will be measured. It is distinct from operations, which execute the defined strategy."),
  q(5,"Governance and Compliance","multiple-choice","Which regulatory framework governs the collection, processing, and protection of personal data belonging to EU residents?",["HIPAA","PCI DSS","GDPR","SOX"],2,"**GDPR** (General Data Protection Regulation) applies to any organisation handling EU residents' personal data, regardless of where the organisation is based. It mandates data minimisation, purpose limitation, breach notification, and individual rights."),
  q(5,"Governance and Compliance","multiple-choice","PCI DSS (Payment Card Industry Data Security Standard) applies to:",["All companies with more than 500 employees","Organisations that process, store, or transmit credit and debit card data","Healthcare providers storing patient records","Government agencies with classified data"],1,"**PCI DSS** is a contractual standard (not a law) mandated by card brands (Visa, Mastercard, etc.). Any organisation that handles payment card data must comply, with requirements covering encryption, access control, and network security."),
  q(5,"Governance and Compliance","multiple-choice","Which governance document provides detailed, step-by-step instructions for HOW a specific task or process should be performed?",["Policy","Standard","Guideline","Procedure"],3,"**Procedures** are step-by-step instructions — they tell employees exactly how to perform a task (e.g. how to respond to a phishing report). **Policies** set intent; **standards** set measurable requirements; **guidelines** are recommendations."),
  q(5,"Governance and Compliance","multiple-choice","A security policy is BEST described as:",["A technical configuration guide for firewall rules","A high-level management statement of intent that establishes the organisation's security requirements and expectations","A detailed checklist for system hardening","A recommendation that employees may choose to follow at their discretion"],1,"**Policies** are mandatory management directives — they state WHAT must be done and WHY, but not HOW. They are approved by senior leadership, apply organisation-wide, and form the foundation of the security programme."),
  q(5,"Governance and Compliance","true-false","HIPAA (Health Insurance Portability and Accountability Act) requires US healthcare organisations and their business associates to protect Protected Health Information (PHI).",["True","False"],0,"**True.** **HIPAA** establishes federal standards for protecting PHI in the USA. The Security Rule specifies administrative, physical, and technical safeguards for electronic PHI (ePHI). Violations can result in significant civil and criminal penalties."),
  q(5,"Governance and Compliance","true-false","Guidelines are mandatory requirements that all employees must comply with, similar to policies.",["True","False"],1,"**False.** **Guidelines** are recommendations — best practices that employees should consider but are not required to follow. **Policies** and **procedures** are mandatory. Guidelines provide flexibility where strict rules may not be appropriate."),

  // Audits and Assessments
  q(5,"Audits and Assessments","multiple-choice","What distinguishes a penetration test from a vulnerability assessment?",["A vulnerability assessment requires greater expertise and is more expensive","A penetration test actively attempts to exploit discovered vulnerabilities to confirm impact; a vulnerability assessment only identifies them","Vulnerability assessments are always performed by external parties","Penetration tests only target web applications"],1,"**Vulnerability assessments** scan for and list potential weaknesses. **Penetration tests** go further — they attempt to exploit those weaknesses to demonstrate real-world impact and answer: 'What can an attacker actually do with this vulnerability?'"),
  q(5,"Audits and Assessments","multiple-choice","A 'white box' penetration test means the tester:",["Has no prior knowledge of the target environment","Has been given full knowledge of the target's architecture, systems, source code, and credentials","Has partial knowledge of the target, such as network diagrams but not credentials","Focuses exclusively on white-listed external IP addresses"],1,"In a **white box** (crystal box) test, the tester has full visibility — documentation, credentials, architecture diagrams. This maximises coverage and depth of testing but does not simulate a blind external attacker scenario."),
  q(5,"Audits and Assessments","multiple-choice","The purpose of a security audit is BEST described as:",["Actively exploiting vulnerabilities to demonstrate impact","Evaluating whether an organisation's security controls meet established policies, standards, and regulatory requirements","Training employees in security awareness","Monitoring network traffic for anomalies in real time"],1,"A **security audit** is a systematic evaluation of security controls against a defined standard (policy, regulation, or framework). It produces findings and recommendations but does not involve exploitation of vulnerabilities."),
  q(5,"Audits and Assessments","multiple-choice","Passive reconnaissance in penetration testing involves:",["Probing the target's systems directly with port scanners","Gathering publicly available information about the target without directly interacting with its systems","Attempting to exploit identified vulnerabilities","Sending phishing emails to target employees"],1,"**Passive reconnaissance** (OSINT) gathers intelligence through public sources — company websites, LinkedIn, WHOIS records, job postings, social media — without touching the target's systems. It avoids detection and generates no logs on the target."),
  q(5,"Audits and Assessments","multiple-choice","Attestation of findings in a security assessment refers to:",["The process of exploiting discovered vulnerabilities","A formal declaration that the assessment results are accurate and complete, signed off by the appropriate authority","Sharing assessment results with regulatory bodies","Automatically remediating findings identified in the assessment"],1,"**Attestation** is formal sign-off — the assessor certifies that the work was performed correctly and the findings are accurate. This gives the results legal weight and holds the assessor accountable for the quality of their work."),
  q(5,"Audits and Assessments","true-false","An internal security audit is performed by the organisation's own team, while an external audit is conducted by an independent third party.",["True","False"],0,"**True.** **Internal audits** provide continuous oversight but may suffer from organisational bias. **External audits** by independent parties provide objectivity and are often required for regulatory compliance (e.g. PCI DSS mandates external QSA assessments for higher merchant levels)."),
  q(5,"Audits and Assessments","true-false","Bug bounty programmes are a form of responsible disclosure that incentivise external security researchers to report vulnerabilities in exchange for rewards.",["True","False"],0,"**True.** **Bug bounty** programmes (e.g. HackerOne, Bugcrowd) pay researchers for valid vulnerability reports. They provide a continuous, cost-effective source of security testing by the broader security community, following responsible disclosure guidelines."),

  // Security Awareness
  q(5,"Security Awareness","multiple-choice","The PRIMARY goal of an organisational security awareness programme is to:",["Install antivirus software on all employee devices","Educate employees about security risks and their specific role in protecting the organisation","Implement technical security controls such as firewalls","Conduct penetration testing of internal systems"],1,"Security awareness programmes target the **human element** — often the weakest link. Educated employees who recognise threats, follow policies, and report incidents are among the most effective security controls available."),
  q(5,"Security Awareness","multiple-choice","The MOST effective approach to reducing insider threat risk combines:",["Monitoring all employee communications and blocking all personal internet access","Technical controls (least privilege, monitoring, PAM) with a positive security culture and clear reporting channels","Annual security awareness training alone","Assigning all sensitive work to external contractors"],1,"Addressing insider threats requires **layered controls**: technical (least privilege, access monitoring, DLP), procedural (background checks, separation of duties), and cultural (trust, psychological safety for reporting concerns). No single measure is sufficient."),
  q(5,"Security Awareness","multiple-choice","Which of the following represents a password management BEST practice?",["Reusing the same complex password across multiple accounts","Using a password manager to generate and securely store unique, strong passwords for every account","Changing passwords only when required to by policy","Writing passwords on paper kept in a desk drawer"],1,"**Password managers** generate high-entropy unique passwords for every site and store them encrypted, protected by a single strong master password and MFA. This eliminates password reuse — one of the most common causes of account compromise."),
  q(5,"Security Awareness","multiple-choice","A simulated phishing campaign is used to:",["Launch actual attacks against competitors to test their defences","Test and measure employee susceptibility to phishing, then provide targeted follow-up training to those who were deceived","Identify technical vulnerabilities in the email gateway","Replace the need for security awareness training"],1,"**Simulated phishing** measures the human attack surface. Results show which teams or individuals need targeted training, track improvement over time, and reinforce vigilance. The goal is education, not punishment."),
  q(5,"Security Awareness","true-false","Remote and hybrid workers often represent an elevated security risk due to working on less-controlled home networks and personal devices.",["True","False"],0,"**True.** Home networks may lack enterprise-grade controls (next-gen firewalls, IPS, DNS filtering). Personal devices may be unpatched or shared with family members. VPN, MFA, and endpoint management are critical compensating controls for remote workers."),
  q(5,"Security Awareness","true-false","Delivering security awareness training once at employee onboarding is sufficient to maintain a strong security culture.",["True","False"],1,"**False.** Security threats evolve constantly. A one-time training session is quickly forgotten. Effective programmes include regular refresher training, phishing simulations, topic-specific modules triggered by events (e.g. a new phishing campaign in the news), and continuous reinforcement."),
]
